import functools
from typing import ForwardRef, Union, List, Any, Dict
from fastapi.dependencies.utils import get_typed_signature

# Define a class for forward reference
class User:
    pass

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

def read_root(user: "User") -> str:
    return "Hello"

# We need to make sure the wrapper is defined in a different module or 
# the globals are different to trigger NameError.
# Actually, if we define User in the global scope and the function in the same, 
# it should work. 
# But if the function is defined in a module where User is NOT available, 
# and then wrapped, it might fail.

def test_wrapped_method_type_inference():
    # To simulate the issue, we need the function to be defined in a scope 
    # where 'User' is available, but the wrapper to be in a scope where it's not.
    # Or more simply, the wrapper's __globals__ doesn't have 'User'.

    # Let's try to create a function in a dummy module.
    import types
    module_a = types.ModuleType("module_a")
    module_a.User = User

    def make_func(mod):
        def read_root(user: "User") -> str:
            return "Hello"
        read_root.__module__ = mod.__name__
        return read_root

    func = make_func(module_a)

    # Now wrap it. The wrapper will be in __main__
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)

    # The wrapper's __globals__ is __main__, which has User.
    # Wait, if the wrapper's __globals__ has User, it will work.
    # The issue is when the wrapper's __globals__ DOES NOT have User, 
    # but the original function's __globals__ DOES.

    # Let's try this:
    module_b = types.ModuleType("module_b")
    # module_b does NOT have User.

    def make_wrapper(mod, f):
        def wrapped(*args, **kwargs):
            return f(*args, **kwargs)
        wrapped.__module__ = mod.__name__
        wrapped.__globals__ = mod.__dict__
        functools.update_wrapper(wrapped, f)
        return wrapped

    wrapped_func = make_wrapper(module_b, func)

    try:
        get_typed_signature(wrapped_func)
        print("Success!")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
        raise e
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e

if __name__ == "__main__":
    test_wrapped_method_type_inference()

